package com.smartagri.controller; import com.smartagri.model.Models.*; import com.smartagri.service.KnowledgeService; import org.springframework.web.bind.annotation.*; import java.util.List; @RestController @RequestMapping("/api") @CrossOrigin public class KnowledgeController {private final KnowledgeService s; public KnowledgeController(KnowledgeService s){this.s=s;} @GetMapping("/schemes") public List<Scheme> schemes(){return s.schemes();} @GetMapping("/animals") public List<Animal> animals(){return s.animals();} @GetMapping("/plants") public List<Plant> plants(){return s.plants();} @GetMapping("/seeds") public List<Seed> seeds(){return s.seeds();} @GetMapping("/waste-solutions") public List<WasteSolution> waste(){return s.waste();} @GetMapping("/energy") public List<EnergyOption> energy(){return s.energy();}}
